// ---- layers ----
// conv1: conv3x3 (broadcast), one channel, 16x16 -> 14x14, ReLU, >> 4
static inline void conv1_ch(const int8_t *restrict in, const int8_t *restrict k, int32_t *restrict out) {
    const int32_t k0 = k[0], k1 = k[1], k2 = k[2], k3 = k[3], k4 = k[4], k5 = k[5], k6 = k[6], k7 = k[7], k8 = k[8];
    for (int y = 0; y < 14; y++) {
        const int8_t *r0 = in + y * 16, *r1 = r0 + 16, *r2 = r1 + 16;
        int32_t *o = out + y * 14;
        for (int x = 0; x < 14; x++) {
            int32_t s = k0 * r0[x] + k1 * r0[x + 1] + k2 * r0[x + 2]
                      + k3 * r1[x] + k4 * r1[x + 1] + k5 * r1[x + 2]
                      + k6 * r2[x] + k7 * r2[x + 1] + k8 * r2[x + 2];
            o[x] = (int32_t)((s > 0 ? s : 0) >> 4);
        }
    }
}

// dw1: conv3x3 (depthwise), one channel, 14x14 -> 12x12, ReLU, >> 4
static inline void dw1_ch(const int32_t *restrict in, const int8_t *restrict k, int32_t *restrict out) {
    const int32_t k0 = k[0], k1 = k[1], k2 = k[2], k3 = k[3], k4 = k[4], k5 = k[5], k6 = k[6], k7 = k[7], k8 = k[8];
    for (int y = 0; y < 12; y++) {
        const int32_t *r0 = in + y * 14, *r1 = r0 + 14, *r2 = r1 + 14;
        int32_t *o = out + y * 12;
        for (int x = 0; x < 12; x++) {
            int32_t s = k0 * r0[x] + k1 * r0[x + 1] + k2 * r0[x + 2]
                      + k3 * r1[x] + k4 * r1[x + 1] + k5 * r1[x + 2]
                      + k6 * r2[x] + k7 * r2[x + 1] + k8 * r2[x + 2];
            o[x] = (int32_t)((s > 0 ? s : 0) >> 4);
        }
    }
}

// pool1: maxpool 2x2, one channel, 12x12 -> 6x6
static inline void pool1_ch(const int32_t *restrict in, int32_t *restrict out) {
    for (int y = 0; y < 6; y++) {
        const int32_t *r0 = in + 2 * y * 12, *r1 = r0 + 12;
        for (int x = 0; x < 6; x++) {
            int32_t a = r0[2 * x], b = r0[2 * x + 1], c = r1[2 * x], d = r1[2 * x + 1];
            int32_t ab = a > b ? a : b, cd = c > d ? c : d;
            out[y * 6 + x] = ab > cd ? ab : cd;
        }
    }
}

// dw2: conv3x3 (depthwise), one channel, 6x6 -> 4x4, ReLU, >> 4
static inline void dw2_ch(const int32_t *restrict in, const int8_t *restrict k, int32_t *restrict out) {
    const int32_t k0 = k[0], k1 = k[1], k2 = k[2], k3 = k[3], k4 = k[4], k5 = k[5], k6 = k[6], k7 = k[7], k8 = k[8];
    for (int y = 0; y < 4; y++) {
        const int32_t *r0 = in + y * 6, *r1 = r0 + 6, *r2 = r1 + 6;
        int32_t *o = out + y * 4;
        for (int x = 0; x < 4; x++) {
            int32_t s = k0 * r0[x] + k1 * r0[x + 1] + k2 * r0[x + 2]
                      + k3 * r1[x] + k4 * r1[x + 1] + k5 * r1[x + 2]
                      + k6 * r2[x] + k7 * r2[x + 1] + k8 * r2[x + 2];
            o[x] = (int32_t)((s > 0 ? s : 0) >> 4);
        }
    }
}

// pool2: maxpool 2x2, one channel, 4x4 -> 2x2
static inline void pool2_ch(const int32_t *restrict in, int32_t *restrict out) {
    for (int y = 0; y < 2; y++) {
        const int32_t *r0 = in + 2 * y * 4, *r1 = r0 + 4;
        for (int x = 0; x < 2; x++) {
            int32_t a = r0[2 * x], b = r0[2 * x + 1], c = r1[2 * x], d = r1[2 * x + 1];
            int32_t ab = a > b ? a : b, cd = c > d ? c : d;
            out[y * 2 + x] = ab > cd ? ab : cd;
        }
    }
}

// norm0: ReLU + dynamic power-of-two requantization to 0..127, 320 values
static inline void norm0(const int32_t *restrict in, int8_t *restrict out) {
    int32_t mx = -INT32_MAX;
    for (int i = 0; i < 320; i++) if (in[i] > mx) mx = in[i];
    int shift = 0;
    for (int32_t s = mx >> 7; s > 0; s >>= 1) shift++;
    const int32_t rnd = (1 << shift) >> 1;
    for (int i = 0; i < 320; i++) {
        int32_t v = in[i];
        if (v < 0) { out[i] = 0; continue; }
        v = (v + rnd) >> shift;
        out[i] = (int8_t)(v > 127 ? 127 : v);
    }
}

// fc1: linear 320 -> 96, int8 weights
static inline void fc1(const int8_t *restrict in, int32_t *restrict out) {
    const int8_t *w = fc1_w;
    for (int o = 0; o < 96; o++) {
        int32_t sum = 0;
        for (int i = 0; i < 320; i++) sum += (int32_t)*w++ * in[i];
        out[o] = sum;
    }
}

// norm1: ReLU + dynamic power-of-two requantization to 0..127, 96 values
static inline void norm1(const int32_t *restrict in, int8_t *restrict out) {
    int32_t mx = -INT32_MAX;
    for (int i = 0; i < 96; i++) if (in[i] > mx) mx = in[i];
    int shift = 0;
    for (int32_t s = mx >> 7; s > 0; s >>= 1) shift++;
    const int32_t rnd = (1 << shift) >> 1;
    for (int i = 0; i < 96; i++) {
        int32_t v = in[i];
        if (v < 0) { out[i] = 0; continue; }
        v = (v + rnd) >> shift;
        out[i] = (int8_t)(v > 127 ? 127 : v);
    }
}

// fc2: linear 96 -> 64, int8 weights
static inline void fc2(const int8_t *restrict in, int32_t *restrict out) {
    const int8_t *w = fc2_w;
    for (int o = 0; o < 64; o++) {
        int32_t sum = 0;
        for (int i = 0; i < 96; i++) sum += (int32_t)*w++ * in[i];
        out[o] = sum;
    }
}

// norm2: ReLU + dynamic power-of-two requantization to 0..127, 64 values
static inline void norm2(const int32_t *restrict in, int8_t *restrict out) {
    int32_t mx = -INT32_MAX;
    for (int i = 0; i < 64; i++) if (in[i] > mx) mx = in[i];
    int shift = 0;
    for (int32_t s = mx >> 7; s > 0; s >>= 1) shift++;
    const int32_t rnd = (1 << shift) >> 1;
    for (int i = 0; i < 64; i++) {
        int32_t v = in[i];
        if (v < 0) { out[i] = 0; continue; }
        v = (v + rnd) >> shift;
        out[i] = (int8_t)(v > 127 ? 127 : v);
    }
}

// fc3: linear 64 -> 10, int8 weights
static inline void fc3(const int8_t *restrict in, int32_t *restrict out) {
    const int8_t *w = fc3_w;
    for (int o = 0; o < 10; o++) {
        int32_t sum = 0;
        for (int i = 0; i < 64; i++) sum += (int32_t)*w++ * in[i];
        out[o] = sum;
    }
}

uint32_t ref_infer(const int8_t img[REF_IMG_PIXELS], int32_t logits[REF_N_CLASSES]) {
    PROF_BEGIN();
    for (int c = 0; c < 80; c++) {
        conv1_ch(img, conv1_w + 9 * c, ch_a);
        PROF_STAGE(0);
        dw1_ch(ch_a, dw1_w + 9 * c, ch_b);
        PROF_STAGE(1);
        pool1_ch(ch_b, ch_a);
        PROF_STAGE(2);
        dw2_ch(ch_a, dw2_w + 9 * c, ch_b);
        PROF_STAGE(3);
        pool2_ch(ch_b, feat + 4 * c);
        PROF_STAGE(4);
    }
    norm0(feat, act);
    fc1(act, acc);
    PROF_STAGE(5);
    norm1(acc, act);
    fc2(act, acc);
    PROF_STAGE(6);
    norm2(acc, act);
    fc3(act, logits);
    PROF_STAGE(7);
    uint32_t best = 0;
    for (uint32_t i = 1; i < 10; i++) if (logits[i] > logits[best]) best = i;
    return best;
}
